python3 << 'EOF'
import zipfile, re
from xml.etree import ElementTree as ET
ns = {'m': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
z = zipfile.ZipFile('budget.xlsx')
root = ET.fromstring(z.read('xl/worksheets/sheet1.xml'))

expenses = []
for row in root.findall('m:sheetData/m:row', ns):
    r = int(row.get('r'))
    if 11 <= r <= 22:  # expense line items (excluding Total Expenses row 23)
        for c in row.findall('m:c', ns):
            if c.get('r').startswith('C'):
                v = c.find('m:v', ns)
                if v is not None:
                    expenses.append((r, v.text))

total = sum(float(v) for _, v in expenses)
print("Expense line items (col C):")
for r, v in expenses:
    print(f"  Row {r}: {v}")
print(f"\nTOTAL EXPENSES = {total:,.2f}")

# Category breakdown
cats = {}
for row in root.findall('m:sheetData/m:row', ns):
    r = int(row.get('r'))
    if 11 <= r <= 22:
        a = cval = None
        for c in row.findall('m:c', ns):
            ref = c.get('r')
            is_el = c.find('m:is', ns)
            if is_el is not None:
                txt = ''.join(x.text or '' for x in is_el.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t'))
            else:
                v = c.find('m:v', ns)
                txt = v.text if v is not None else None
            if ref.startswith('A'): a = txt
            if ref.startswith('C'): cval = float(txt) if txt else 0
        if a and cval:
            cats[a] = cats.get(a, 0) + cval
print("\nBy category:")
for k, v in cats.items():
    print(f"  {k}: {v:,.2f}")
